package com.joysistvi.CyberAccess.service;
import com.joysistvi.CyberAccess.model.FoodCat; import com.joysistvi.CyberAccess.repo.*; import java.sql.SQLException; import java.util.List;
public class FoodCatServiceImpl { private final FoodCatRepo repo; public FoodCatServiceImpl(){this(new FoodCatRepoImpl());} public FoodCatServiceImpl(FoodCatRepo r){repo=r;}
 public List<FoodCat> getAll()throws SQLException{return repo.findAll();} public FoodCat getById(int id)throws SQLException{return repo.findById(Validation.id(id)).orElse(null);} public void add(FoodCat x)throws SQLException{if(x==null)throw new IllegalArgumentException("Category is required.");x.setName(Validation.text(x.getName(),"Category name",50));repo.save(x);} public boolean update(FoodCat x)throws SQLException{if(x==null)throw new IllegalArgumentException("Category is required.");Validation.id(x.getId());x.setName(Validation.text(x.getName(),"Category name",50));return repo.update(x);} public boolean delete(int id)throws SQLException{return repo.delete(Validation.id(id));}}
